INSERT INTO metric_definitions (metric_key, version, label, surface, unit, confidence, formula, session_basis, basis_label, grains, direction, comparison_mode, treatment, source_tables, effective_from, effective_to, change_note, created_at) VALUES
  ('refund_value', 3, 'Refunds', 'post_purchase', 'EGP', 'measured', 'Σ Shopify refunded amounts + Σ (goods value − return shipping fee − restocking fee) on approved Yanet returns, by the order''s week', NULL, NULL, '["week","product","size","governorate","reason"]', 'lower_better', 'drop_day', 'The cash the customer actually receives, which is what the courier''s remittance is short by. The fees are withheld from the refund, not paid by the business. Two channels, never double-counted: Shopify''s own refunds, and approved Yanet returns the courier pays back.', '["fact_refund"]', '1970-01-03', NULL, 'v3: refunds are net of the fees the customer pays, and returned goods are credited back to COGS.', '2026-09-16T00:00:00Z'),
  ('return_cost', 2, 'Return cost', 'post_purchase', 'EGP', 'modelled', 'refund_value − the cost of the returned goods, which go back on the shelf', NULL, NULL, '["week","product"]', 'lower_better', 'drop_day', 'What a return leaves behind once the goods are back and sellable: the cash that left, less what those goods cost. Where a returned unit has no cost on file it cannot be credited, and coverage says how much of the return could be.', '["fact_refund","fact_refund_line","dim_geo"]', '1970-01-03', NULL, 'v3: refunds are net of the fees the customer pays, and returned goods are credited back to COGS.', '2026-09-16T00:00:00Z'),
  ('contribution_margin', 3, 'Contribution margin', 'economics', 'EGP', 'modelled', 'gross_profit − ad_spend − fulfilment_cost_outbound − cod_collection_fees − rto_shipping_waste − refund_value + returned goods COGS', NULL, NULL, '["week","drop","offer"]', 'higher_better', 'drop_day', 'Modelled while any component is modelled (freight, COD fees). Refunds leave net of the fees the customer pays, and returned stock is credited back at what it cost, because it goes back on the shelf. A returned unit with no cost on file cannot be credited and reads slightly pessimistic. The objective function (§0): delivered contribution margin per drop.', '["fact_order","fact_order_line","dim_variant","fact_ad_daily","fact_reversal","dim_geo"]', '1970-01-03', NULL, 'v3: refunds subtracted net of customer-paid fees, and returned goods credited back to COGS since they are restocked.', '2026-09-16T00:00:00Z');
